Assets/Tests/Editor/EconomyIntegrationRe:
using System;
using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;
using UnityEngine;

public sealed class EconomyIntegrationRegressionTests
{
    private readonly List<UnityEngine.Object> createdObjects = new();

    [SetUp]
    public void SetUp()
    {
        foreach (GameObject manager in UnityEngine.Object.FindObjectsOfType<GameObject>()
                     .Where(item => item.GetComponent<GameManager>() != null ||
                                    item.GetComponent<ResourceManager>() != null ||
                                    item.GetComponent<BuildingManager>() != null ||
                                    item.GetComponent<ResearchManager>() != null ||
                                    item.GetComponent<WorkshopManager>() != null ||
                                    item.GetComponent<SimulationManager>() != null ||
                                    item.GetComponent<SaveManager>() != null))
            UnityEngine.Object.DestroyImmediate(manager);
        ProgressionModifierManager.Rebuild(null);
    }

    [TearDown]
    public void TearDown()
    {
        for (int i = createdObjects.Count - 1; i >= 0; i--)
            UnityEngine.Object.DestroyImmediate(createdObjects[i]);
        createdObjects.Clear();
        ProgressionModifierManager.Rebuild(null);
    }

    [Test]
    public void MachineFactory_CompletedResearchAllowsConstructionWithoutPrecisionTooling()
    {
        GameManager game = CreateManager<GameManager>("FactoryVisibility-Game");
        ResourceManager resources = CreateManager<ResourceManager>("FactoryVisibility-Resources");
        BuildingManager buildings = CreateManager<BuildingManager>("FactoryVisibility-Buildings");
        ResearchManager research = CreateManager<ResearchManager>("FactoryVisibility-Research");
        WorkshopManager workshop = CreateManager<WorkshopManager>("FactoryVisibility-Workshop");
        workshop.ResetForLoadForEditor();
        game.State.RestoreCoreForEditor(0, TechLevel.Industrial, new ExpantaNum("1e9"), 0L);
        game.State.RestorePopulationForEditor(new ExpantaNum(10000));
        game.State.ResetDerivedEconomyForEditor(new ExpantaNum(100000));
        BuildingDef factory = DataBase<BuildingDef>.Find("MachineFactory");
        Assert.That(buildings.ShouldDisplay(factory), Is.False);
        foreach (ResearchDef prerequisite in factory.RequiredResearch)
        {
            ResearchState state = research.GetState(prerequisite);
            state.RestoreForEditor(state.BaseCost, true, true, PaidCostsFor(prerequisite));
        }
        foreach (Pair<ResourceDef, ExpantaNum> cost in factory.ResourceRequirements)
            resources.SetAmount(cost.First, new ExpantaNum("1e9"));

        Assert.That(buildings.ShouldDisplay(factory), Is.True,
            "Completing the factory research must reveal a directly buildable card.");
        Assert.That(workshop.IsPurchased(DataBase<WorkshopUpgradeDef>.Find("PrecisionTooling")), Is.False);
        Assert.That(buildings.CanConstructNew(factory), Is.True);
        Assert.That(buildings.TryBuild(factory, ExpantaNum.One, out BuildFailure failure), Is.True, failure.ToString());
        Assert.That(buildings.GetState(factory).Amount, Is.EqualTo(ExpantaNum.One)); // Discrete building count.
    }

    [TestCase(false)]
    [TestCase(true)]
    public void ChemicalPlant_RocketFuelWaitsForOrbitalEngineeringAndStartsInExistingPlant(bool offline)
    {
        GameManager game = CreateManager<GameManager>("FuelGate-Game");
        ResourceManager resources = CreateManager<ResourceManager>("FuelGate-Resources");
        BuildingManager buildings = CreateManager<BuildingManager>("FuelGate-Buildings");
        ResearchManager research = CreateManager<ResearchManager>("FuelGate-Research");
        SimulationManager simulation = CreateManager<SimulationManager>("FuelGate-Simulation");
        game.State.AdvanceTechLevelForEditor(TechLevel.Industrial);
        game.State.RestorePopulationCapacityExactForEditor(new ExpantaNum(3000), ExpantaNum.Zero);
        game.State.RestorePopulationForEditor(new ExpantaNum(2000));
        foreach (ResearchDef definition in DataBase<ResearchDef>.All)
        {
            if (definition.TechLevel > TechLevel.Industrial) continue;
            ResearchState state = research.GetState(definition);
            state.RestoreForEditor(state.BaseCost, true, true, PaidCostsFor(definition));
        }
        ProgressionModifierManager.Rebuild(research.States.Values.ToArray());
        foreach (ResourceDef resource in DataBase<ResourceDef>.All)
            resources.SetAmount(resource, new ExpantaNum(100000));
        foreach (string id in new[] { "IrrigationWorks", "CentralPowerStation", "Caravanserai", "ChemicalPlant" })
            buildings.SetAmountAndRatesForEditor(buildings.EnsureBuilding(DataBase<BuildingDef>.Find(id)),
                id == "IrrigationWorks" ? new ExpantaNum(100) : id == "ChemicalPlant" ? ExpantaNum.One : new ExpantaNum(4));
        ResourceDef fuel = DataBase<ResourceDef>.Find("RocketFuel");
        ResourceDef chemical = DataBase<ResourceDef>.Find("Chemical");
        ResourceDef explosives = DataBase<ResourceDef>.Find("Explosives");
        resources.SetAmount(fuel, ExpantaNum.Zero);
        resources.SetAmount(chemical, ExpantaNum.Zero);
        resources.SetAmount(explosives, ExpantaNum.Zero);
        if (offline) simulation.AdvanceOffline(1d);
        else simulation.ManualTick(1d);

        Assert.That(resources.GetAmount(chemical), Is.GreaterThan(ExpantaNum.Zero));
        Assert.That(resources.GetAmount(explosives), Is.GreaterThan(ExpantaNum.Zero));
        Assert.That(resources.GetAmount(fuel).ToDouble(), Is.InRange(0d, 1e-8d),
            "Industrial chemistry must not stockpile rocket propellant before orbital engineering.");
        ProgressionModifierState locked = ProgressionModifierManager.Current;
        ResearchDef orbital = DataBase<ResearchDef>.Find("OrbitalEngineering");
        ResearchState orbitalState = research.GetState(orbital);
        orbitalState.RestoreForEditor(orbitalState.BaseCost - new ExpantaNum(.01d), true, false, PaidCostsFor(orbital));
        Assert.That(research.StartResearch(orbital), Is.True);
        simulation.ManualTick(.1d);
        Assert.That(research.IsResearchCompleted(orbital.Id), Is.True);
        Assert.That(resources.GetState(fuel).ProductionRate, Is.GreaterThan(ExpantaNum.Zero),
            "Completing the research must refresh the already operating chemical plant immediately.");
        Assert.That(locked.GetBuildingResourceProductionMultiplier(DataBase<BuildingDef>.Find("ChemicalPlant"), fuel)
            .ToDouble(), Is.InRange(0d, 1e-8d), "The previous modifier snapshot must retain the locked rate.");
        if (offline) simulation.AdvanceOffline(1d);
        else simulation.ManualTick(1d);
        Assert.That(resources.GetAmount(fuel), Is.GreaterThan(ExpantaNum.Zero));

        var savedResearch = new SaveManager.ResearchSaveData
        {
            GlobalEfficiencyFactor = "1",
            States = research.States.Values.Where(state => state.Status == ResearchStatus.Completed)
                .Select(state => new SaveManager.ResearchStateSaveData
                {
                    ResearchId = state.Definition.Id, Progress = state.Progress.ToString(),
                    CostPaid = state.CostPaid, Completed = true,
                    PaidResourceCosts = PaidCostsFor(state.Definition).Select(cost =>
                        new SaveManager.ResearchResourceCostSaveData
                        { ResourceId = cost.Key.Id, Amount = cost.Value.ToString() }).ToList()
                }).ToList()
        };
        double rateBeforeReload = resources.GetState(fuel).ProductionRate.ToDouble();
        var industrialResearch = JsonUtility.FromJson<SaveManager.ResearchSaveData>(JsonUtility.ToJson(savedResearch));
        // Preserve the applied industrial rewards while restoring the fuel gate's earlier research state.
        industrialResearch.States.RemoveAll(state => state.ResearchId == orbital.Id);
        research.RestoreSaveDataForEditor(industrialResearch);
        Assert.That(resources.GetState(fuel).ProductionRate.ToDouble(), Is.InRange(0d, 1e-8d));
        research.RestoreSaveDataForEditor(JsonUtility.FromJson<SaveManager.ResearchSaveData>(
            JsonUtility.ToJson(savedResearch)));
        Assert.That(resources.GetState(fuel).ProductionRate.ToDouble(),
            Is.EqualTo(rateBeforeReload).Within(1e-6d), "Restoring research must restore the fuel gate without duplicating production.");
    }

    [Test]
    public void SectorFacilityDisablePreservesOwnershipAndCapacityAndRestoresAllFlows()
    {
        GameManager game = CreateManager<GameManager>("Facility-Game");
        ResourceManager resources = CreateManager<ResourceManager>("Facility-Resources");
        BuildingManager buildings = CreateManager<BuildingManager>("Facility-Buildings");
        ResearchManager research = CreateManager<ResearchManager>("Facility-Research");
        game.State.RestorePopulationForEditor(1000);
        SectorBuildingDef facility = ScriptableObject.CreateInstance<SectorBuildingDef>();
        createdObjects.Add(facility);
        facility.name = "ControlledFacility";
        facility.SetIdForEditor("ControlledFacility");
        // WoodLog has a permanent starter income, so use an input with no passive source.
        ResourceDef input = DataBase<ResourceDef>.Find("Clay");
        ResourceDef output = DataBase<ResourceDef>.Find("StoneChunk");
        facility.ConfigureEconomyForEditor(1.1d, 0, 2, 3, 20, 5, 20, 2, 100, 27, 36, 0, 0,
            new List<Pair<ResourceDef, ExpantaNum>>(),
            new List<Pair<ResourceDef, ExpantaNum>> { new(output, 7) },
            new List<Pair<ResourceDef, ExpantaNum>> { new(input, 6) });
        resources.SetAmount(input, 10000);
        BuildingState state = buildings.EnsureBuilding(facility);
        buildings.SetAmountAndRatesForEditor(state, 1);
        buildings.PrepareTickResourceSatisfactionForEditor(1d);
        ExpantaNum amount = state.Amount;
        ExpantaNum inputAmount = resources.GetAmount(input);
        ExpantaNum outputAmount = resources.GetAmount(output);
        ExpantaNum foodCapacity = game.State.FoodCapacity;
        ExpantaNum housing = game.State.Population.PopulationCapacity;
        ExpantaNum territory = game.State.TerritoryUsed;
        ExpantaNum foodBase = game.State.FoodProductionRate - facility.FoodProductionRate * state.Efficiency;
        ExpantaNum production = resources.GetState(output).ProductionRate;
        ExpantaNum consumption = resources.GetState(input).ConsumptionRate;
        ExpantaNum researchPower = research.ResearchPower;
        ExpantaNum productivity = buildings.TotalProductivity;
        Assert.That(production, Is.GreaterThan(ExpantaNum.Zero));
        Assert.That(consumption, Is.GreaterThan(ExpantaNum.Zero));
        Assert.That(buildings.GetDeconstructionPreview(facility, 1), Is.Not.Null);
        Assert.That(buildings.SetSectorBuildingEnabled(facility, false), Is.True);
        int version = state.Version;
        Assert.That(buildings.SetSectorBuildingEnabled(facility, false), Is.True);
        Assert.That(state.Version, Is.EqualTo(version), "Repeated stop is idempotent.");
        buildings.PrepareTickResourceSatisfactionForEditor(1d);
        Assert.That(state.IsEnabled, Is.False);
        Assert.That(state.Amount == amount, Is.True, "Discrete building count is preserved.");
        Assert.That(resources.GetAmount(input).ToDouble(), Is.EqualTo(inputAmount.ToDouble()).Within(1e-6));
        Assert.That(resources.GetAmount(output).ToDouble(), Is.EqualTo(outputAmount.ToDouble()).Within(1e-6));
        Assert.That(state.Efficiency.ToDouble(), Is.LessThan(1e-6));
        Assert.That(resources.GetState(output).ProductionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(resources.GetState(input).ConsumptionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.PowerProductionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.PowerConsumptionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.LogisticsProductionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.LogisticsConsumptionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.FoodConsumptionRate.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.FoodProductionRate.ToDouble(), Is.EqualTo(foodBase.ToDouble()).Within(1e-6));
        Assert.That(research.ResearchPower, Is.LessThan(researchPower));
        Assert.That(buildings.TotalProductivity, Is.LessThan(productivity));
        Assert.That(buildings.UsedProductivity.ToDouble(), Is.LessThan(1e-6));
        Assert.That(game.State.FoodCapacity.ToDouble(), Is.EqualTo(foodCapacity.ToDouble()).Within(1e-6));
        Assert.That(game.State.Population.PopulationCapacity.ToDouble(), Is.EqualTo(housing.ToDouble()).Within(1e-6));
        Assert.That(game.State.TerritoryUsed.ToDouble(), Is.EqualTo(territory.ToDouble()).Within(1e-6));
        resources.SetAmount(input, 0);
        Assert.That(buildings.SetSectorBuildingEnabled(facility, true), Is.True);
        buildings.PrepareTickResourceSatisfactionForEditor(1d);
        Assert.That(state.Efficiency.ToDouble(), Is.LessThan(1e-6));
        resources.SetAmount(input, inputAmount);
        buildings.PrepareTickResourceSatisfactionForEditor(1d);
        Assert.That(state.Efficiency, Is.GreaterThan(ExpantaNum.Zero));
        Assert.That(resources.GetState(output).ProductionRate.ToDouble(), Is.EqualTo(production.ToDouble()).Within(1e-5));
        Assert.That(resources.GetState(input).ConsumptionRate.ToDouble(), Is.EqualTo(consumption.ToDouble()).Within(1e-5));
        Assert.That(research.ResearchPower.ToDouble(), Is.EqualTo(researchPower.ToDouble()).Within(1e-5));
        Assert.That(buildings.SetSectorBuildingEnabled(null, false), Is.False);
        SectorBuildingDef absent = ScriptableObject.CreateInstance<SectorBuildingDef>();
        createdObjects.Add(absent);
        Assert.That(buildings.SetSectorBuildingEnabled(absent, false), Is.False);
    }

    [Test]
    public void ParitySnapshot_PreservesPopulationProgressAndResearchQueueOrder()
    {
        GameManager game = CreateManager<GameManager>("ParitySnapshot-Game");
        ResourceManager resources = CreateManager<ResourceManager>("ParitySnapshot-Resources");
        BuildingManager buildings = CreateManager<BuildingManager>("ParitySnapshot-Buildings");
        ResearchManager research = CreateManager<ResearchManager>("ParitySnapshot-Research");
        CreateManager<WorkshopManager>("ParitySnapshot-Workshop");
        CreateManager<SaveManager>("ParitySnapshot-Save");
        SimulationManager simulation = CreateManager<SimulationManager>("ParitySnapshot-Simulation");
        BuildingDef house = DataBase<BuildingDef>.Find("WoodHouse");
        buildings.SetAmountAndRatesForEditor(buildings.EnsureBuilding(house), ExpantaNum.One);
        game.State.RestorePopulationForEditor(ExpantaNum.One);
        simulation.ManualTick(0d);
        foreach (ResourceState state in resources.States.Values)
            resources.SetAmount(state.Definition, ExpantaNum.Zero);
        game.State.RestorePopulationChangeProgressForEditor(new ExpantaNum(0.625d));
        research.HandleResearchAction(DataBase<ResearchDef>.Find("ControlledFire"));
        research.HandleResearchAction(DataBase<ResearchDef>.Find("Agriculture"));
        string[] queue = research.ResearchQueue.Select(state => state.Definition.Id).ToArray();
        // Stable IDs and queue ordering require exact comparison.
        Assert.That(queue, Is.EqualTo(new[] { "ControlledFire", "Agriculture" }));

        int runtimeBuildingCount = buildings.States.Count;
        EconomySnapshotDto snapshot = JsonUtility.FromJson<EconomySnapshotDto>(
            JsonUtility.ToJson(EconomyParitySnapshotExporter.CaptureCurrent()));
        Assert.That(snapshot.FormatVersion, Is.EqualTo(6), "Snapshot schema is a versioned protocol constant.");
        foreach (BuildingDto definition in snapshot.Buildings)
        {
            BuildingDef source = DataBase<BuildingDef>.Find(definition.Id);
            Assert.That(ExpantaNum.Parse(definition.PowerContribution).ToDouble(),
                Is.EqualTo(source.PowerContribution.ToDouble()).Within(1e-6), definition.Id);
            Assert.That(ExpantaNum.Parse(definition.LogisticsContribution).ToDouble(),
                Is.EqualTo(source.LogisticsContribution.ToDouble()).Within(1e-6), definition.Id);
        }
        Assert.That(snapshot.SaveState.Buildings.Select(state => state.BuildingId),
            Is.EquivalentTo(snapshot.Buildings.Select(definition => definition.Id)));
        Assert.That(snapshot.RuntimeState.Buildings.Select(state => state.BuildingId),
            Is.EquivalentTo(snapshot.Buildings.Select(definition => definition.Id)));
        Assert.That(buildings.States.Count, Is.EqualTo(runtimeBuildingCount),
            "Export must materialize zero snapshot entries without creating runtime buildings."); // Discrete count.
        string evidencePath = Environment.GetEnvironmentVariable("KINGDOM_PARITY_SNAPSHOT_PATH");
        if (!string.IsNullOrWhiteSpace(evidencePath))
            System.IO.File.WriteAllText(evidencePath, JsonUtility.ToJson(snapshot, true));
        foreach (SaveStateDto state in new SaveStateDto[] { snapshot.SaveState, snapshot.RuntimeState })
        {
            Assert.That(ExpantaNum.Parse(state.PopulationChangeProgress).ToDouble(),
                Is.EqualTo(0.625d).Within(1e-6d));
            Assert.That(state.QueuedResearchIds, Is.EqualTo(queue));
        }
        simulation.ManualTick(0.1d);
        Assert.That(game.State.Population.PopulationChangeProgress.ToDouble(), Is.InRange(0.625001d, 0.99d));
        if (!string.IsNullOrWhiteSpace(evidencePath))
            EconomyParitySnapshotExporter.ExportCurrent(evidencePath + ".after.json");
    }

