    [Test]
    public void IndustrialFoodProcessWorkshopsUseDistinctGlobalRolesAndEntryAccess()
    {
        WorkshopUpgradeDef first = DataBase<WorkshopUpgradeDef>.Find(
            "IndustrialFoodProcessEngineering");
