            Assert.That(building.PowerContribution, Is.LessThan(ExpantaNum.Zero));
            Assert.That(building.LogisticsContribution,
                building.Id == "OrbitalStation" ? Is.GreaterThan(ExpantaNum.Zero) : Is.LessThan(ExpantaNum.Zero));
